import base64,hashlib,json,os,subprocess
from pathlib import Path
R=Path('/dataset/shaoshitong/search-r1-rl/bapo-fresh200-controller-initfix-20261006')
S='60f566b3ddabc88ce9de56ead5ad30a3d6795dd2'
assert R.resolve()==R and os.uname().nodename=='h100-5'
assert subprocess.check_output(['git','-C',str(R/'repo'),'rev-parse','HEAD'],text=True).strip()==S
receipt=json.loads((R/'scheduler-head/formal200-receipt.json').read_text());assert str(receipt['job_id'])=='3315' and receipt['source']==S
assert hashlib.sha256((R/'logs/tools-manifest.json').read_bytes()).hexdigest()=='fbd0098b946e23a8eb7304912cad01b8f339e249f627c919ddec8313c2337859'
PAYLOAD=[['logs/first5-v3-portable.tar', '2bf7c142975ed3a2c0640b192ecbf075c6b04270b7b4cdc94ff4a8fce4f123f2', ''], ['logs/install-first5-v3-reviewed.py', 'eea9a51b11ed893f73f5437cb8ee4e73fcabee5207de70ed0611d89c2d5053dc', ''], ['logs/reviews/3315-FIRST5-V3-PORTABLE-PREFIX-INDEPENDENT-CODE-REVIEW-V2.json', 'adf19ac3ae2a0ebc96cd695e700413356651235de6660de340d855a8eb6b00b6', '']]
for name,sha,encoded in PAYLOAD:
 p=R/name;assert R in p.parents and p.resolve()==p and not p.exists() and not p.is_symlink()
 raw=base64.b64decode(encoded,validate=True);assert hashlib.sha256(raw).hexdigest()==sha
for name,sha,encoded in PAYLOAD:
 p=R/name;p.parent.mkdir(exist_ok=True)
 with p.open('xb')as f:f.write(base64.b64decode(encoded));f.flush();os.fsync(f.fileno())
 assert hashlib.sha256(p.read_bytes()).hexdigest()==sha
print(json.dumps({'scope':'OWN_V3_CODE_REVIEW_PACKAGE_UPLOAD_ONLY','files':[{ 'path':str(R/n),'sha256':h}for n,h,e in PAYLOAD]}),flush=True)
env=dict(os.environ,PYTHONPATH=str(R/'repo'),PYTHONDONTWRITEBYTECODE='1',CUDA_VISIBLE_DEVICES='',HF_HUB_OFFLINE='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1');env.pop('PYTHONOPTIMIZE',None)
a=[str(R/'env/bin/python'),'-B',str(R/'logs/install-first5-v3-reviewed.py'),'--package',str(R/'logs/first5-v3-portable.tar'),'--expected-package-sha',PAYLOAD[0][1],'--source-commit',S,'--review',str(R/PAYLOAD[2][0]),'--expected-review-sha',PAYLOAD[2][1],'--execute-worker']
p=subprocess.run(a,cwd=str(R/'repo'),env=env)
print(json.dumps({'scope':'ACTUAL_LINUX25_CODE_TOOLS_ONLY_NOT_FIRST5','installer_exit_code':p.returncode}),flush=True)
raise SystemExit(p.returncode)
